// Espera: {idSolicitud, idUsuario, observacion, estado, filas:[...]}
if(!i.idSolicitud || !i.idUsuario || !Array.isArray(i.filas) || i.filas.length===0){
  throw new Error('Entrada inválida para crear versión');
}
return [{json:i}];

