BEGIN;
WITH nextv AS (
  SELECT COALESCE(MAX(numero_version),0)+1 AS n
  FROM versiones WHERE id_solicitud = $1
), insv AS (
  INSERT INTO versiones (id_solicitud, numero_version, id_usuario, observacion)
  SELECT $1, n, $2, $3 FROM nextv
  RETURNING id_version, numero_version
)
SELECT id_version, numero_version FROM insv;

